function initials(name: string) {
  return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase();
}

function StatusPill({ value }: { value: string }) {
  const tone = value === "Present" || value === "Approved" || value === "Online" || value === "Active" || value === "Complete"
    ? "bg-[#e4f4e9] text-[#237349]"
    : value === "Late" || value === "Pending" || value === "Needs sync" || value === "In progress"
      ? "bg-[#fff3d8] text-[#a66d14]"
      : "bg-[#f2e8e5] text-[#a4544d]";
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold ${tone}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{value}</span>;
}

function Avatar({ label, large = false, dark = false }: { label: string; large?: boolean; dark?: boolean }) {
  return <div className={`${large ? "h-11 w-11 text-sm" : "h-8 w-8 text-[11px]"} grid shrink-0 place-items-center rounded-xl font-bold ${dark ? "bg-[#dce9e4] text-[#23493d]" : "bg-[#e6ece8] text-[#2d6252]"}`}>{label}</div>;
}

function SectionHeading({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex items-end justify-between gap-4"><div><div className="mb-2 text-[11px] font-bold uppercase tracking-[0.17em] text-[#719187]">{eyebrow}</div><h1 className="font-display text-[32px] font-semibold leading-none tracking-[-0.035em] text-[#17392f]">{title}</h1>{subtitle && <p className="mt-2 text-sm text-[#789188]">{subtitle}</p>}</div>{action}</div>;
}

function MetricCard({ label, value, change, detail, icon: Icon, tint }: { label: string; value: string; change?: string; detail: string; icon: typeof Users; tint: string }) {
  return <div className="card-lift relative overflow-hidden rounded-2xl border border-[#e5ebe7] bg-white p-5"><div className={`mb-5 grid h-9 w-9 place-items-center rounded-xl ${tint}`}><Icon size={17} /></div><div className="flex items-end justify-between gap-3"><div><div className="text-[12px] font-medium text-[#799087]">{label}</div><div className="mt-1 text-[28px] font-semibold tracking-[-0.04em] text-[#17392f]">{value}</div></div>{change && <span className="mb-1 flex items-center gap-1 text-[11px] font-bold text-[#35855d]"><ArrowUpRight size={13} />{change}</span>}</div><div className="mt-3 text-[11px] text-[#9aaba4]">{detail}</div></div>;
}

